python3 -c "
import json, sys

with open('BellevueWeather/BellevueWeather/BellevueWeather.flow') as f:
    flow = json.load(f)

errors = []
warnings = []

# Build lookup maps
node_ids = {n['id'] for n in flow['nodes']}
edges = flow['edges']

# Check all edges reference valid nodes
for edge in edges:
    if edge['sourceNodeId'] not in node_ids:
        errors.append(f'Edge {edge[\"id\"]}: sourceNodeId {edge[\"sourceNodeId\"]} not found')
    if edge['targetNodeId'] not in node_ids:
        errors.append(f'Edge {edge[\"id\"]}: targetNodeId {edge[\"targetNodeId\"]} not found')

# Check edge chain: start -> getWeather -> convertToCelsius -> formatSummary -> checkTemperature -> end*
def get_successors(node_id):
    return [e['targetNodeId'] for e in edges if e['sourceNodeId'] == node_id]

def get_predecessors(node_id):
    return [e['sourceNodeId'] for e in edges if e['targetNodeId'] == node_id]

chain = ['start', 'getWeather', 'convertToCelsius', 'formatSummary', 'checkTemperature']
for i in range(len(chain)-1):
    succs = get_successors(chain[i])
    if chain[i+1] not in succs:
        errors.append(f'Expected edge {chain[i]} -> {chain[i+1]}, got successors: {succs}')

# Check convertToCelsius node details
conv_node = next((n for n in flow['nodes'] if n['id'] == 'convertToCelsius'), None)
if not conv_node:
    errors.append('convertToCelsius node missing')
else:
    script = conv_node['inputs']['script']
    if 'temperatureF' not in script:
        errors.append('convertToCelsius script missing temperatureF')
    if 'temperatureC' not in script:
        errors.append('convertToCelsius script missing temperatureC')
    if '(tempF - 32)' in script or '- 32' in script:
        print('  [OK] F->C conversion formula present')

# Check formatSummary references convertToCelsius
fmt_node = next((n for n in flow['nodes'] if n['id'] == 'formatSummary'), None)
if fmt_node:
    script = fmt_node['inputs']['script']
    if 'convertToCelsius' not in script:
        errors.append('formatSummary does not reference convertToCelsius')
    if 'temperatureC' not in script:
        errors.append('formatSummary does not include temperatureC in output')
    if 'C)' in script or \"'C'\" in script or '\"C\"' in script or '+tempC' in script or '+ tempC' in script:
        print('  [OK] formatSummary includes Celsius in summary string')

# Check variables
var_ids = {v['id'] for v in flow['variables']['nodes']}
required_vars = ['getWeather.output', 'getWeather.error', 'convertToCelsius.output', 'convertToCelsius.error', 'formatSummary.output', 'formatSummary.error']
for v in required_vars:
    if v not in var_ids:
        errors.append(f'Variable {v} missing from variables.nodes')

# Check layout has all nodes
layout_nodes = set(flow['layout']['nodes'].keys())
for nid in node_ids:
    if nid not in layout_nodes:
        warnings.append(f'Node {nid} missing from layout')

# Report
print()
print('=== FLOW VALIDATION REPORT ===')
print(f'Nodes: {sorted(node_ids)}')
print(f'Edges:')
for e in edges:
    print(f'  {e[\"sourceNodeId\"]} --[{e[\"sourcePort\"]}]--> {e[\"targetNodeId\"]} [{e[\"targetPort\"]}]')
print()
if errors:
    print('ERRORS:')
    for e in errors:
        print(f'  [ERROR] {e}')
    sys.exit(1)
elif warnings:
    print('WARNINGS:')
    for w in warnings:
        print(f'  [WARN] {w}')
    print()
    print('RESULT: VALID WITH WARNINGS')
else:
    print('RESULT: VALID - all checks passed')
"

